const root = $input.first().json;
const body = root.body && typeof root.body === 'object' ? root.body : root;

const userCommand = String(body.userCommand || '').trim();
const draftSpeech = String(body.draftSpeech || '').trim();
const intent = String(body.intent || 'unknown').trim();
const traits = Array.isArray(body.traits) ? body.traits.map(String) : [];
const styleSamples = Array.isArray(body.styleSamples) ? body.styleSamples.map(String).slice(0, 4) : [];
const systemPrompt = String(body.systemPrompt || '').trim();

if (!draftSpeech) {
  return [{ json: { error: 'missing_draft', speech: '' } }];
}

const samplesBlock = styleSamples.length
  ? '\nMUESTRAS DE TU FORMA DE HABLAR (solo estilo, no copies el tema):\n' +
    styleSamples.map((s, i) => `${i + 1}. "${s}"`).join('\n')
  : '';

const traitsBlock = traits.length
  ? '\nREGLAS DE ESTILO:\n- ' + traits.join('\n- ')
  : '';

const system =
  (systemPrompt ||
    'Sos el asistente de voz de Adrian en Nodo Propiedades (Mendoza). Hablá como argentino criollo educado, cálido y profesional.') +
  traitsBlock +
  samplesBlock +
  '\n\nRespondé SOLO con JSON válido: {"speech":"texto para decir en voz alta"}.\n' +
  'Mantené TODOS los datos del borrador (nombres, números, zonas). 1–2 oraciones. Directo. Sin markdown.';

const user = [
  `Comando del usuario: ${userCommand || '(sin comando)'}`,
  `Intención detectada: ${intent}`,
  `Borrador factual (reescribí con tu estilo, sin cambiar datos):\n${draftSpeech}`,
].join('\n');

return [
  {
    json: {
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      draftSpeech,
    },
  },
];

const groq = $input.first().json;
const prep = $('Armar Prompt').first().json;
const draft = String(prep.draftSpeech || '').trim();

const msg = groq.choices?.[0]?.message || {};
let raw =
  (msg.content && String(msg.content).trim()) ||
  String(msg.reasoning || msg.reasoning_content || '').trim();

function stripChe(t) {
  return String(t || '')
    .replace(/\b[Cc]he\b[,.;:!?]*\s*/g, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

let speech = draft;
try {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    if (parsed.speech) speech = String(parsed.speech).trim();
  } else if (raw) {
    speech = raw.replace(/^["']|["']$/g, '').trim();
  }
} catch (e) {
  speech = raw || draft;
}

speech = stripChe(speech);
if (!speech) speech = draft;

return [{ json: { speech, ok: true } }];
